import System.Exception;import System.NullReferenceException;import System.InvalidOperationException;import java.nio.file.*;import java.util.*;
class FoundationExceptionMessageDefaultsProbe{
 static String text(String csv){if(csv.equals("~"))return null;if(csv.isEmpty())return "";String[] p=csv.split(",");char[] c=new char[p.length];for(int i=0;i<c.length;i++)c[i]=(char)Integer.parseInt(p[i]);return new String(c);}static String units(String text){if(text==null)return "~";StringJoiner out=new StringJoiner(",");for(char c:text.toCharArray())out.add(Integer.toString(c));return out.toString();}static void check(boolean ok,String context){if(!ok)throw new AssertionError(context);}
 public static void main(String[] args)throws java.lang.Exception{int cases=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] all=line.split("\t",-1);String owner=all[0];String[] p=Arrays.copyOfRange(all,1,all.length);Class<?> type=Class.forName(owner);int kind=Integer.parseInt(p[2]);Exception inner=kind==1?new InvalidOperationException("inner-value"):kind==2?new NullReferenceException():null;Exception value=(Exception)switch(p[0]){case "default"->type.getConstructor().newInstance();case "message"->type.getConstructor(String.class).newInstance(new Object[]{text(p[1])});case "messageInner"->type.getConstructor(String.class,Exception.class).newInstance(new Object[]{text(p[1]),inner});default->throw new AssertionError(p[0]);};check(units(value.get_Message()).equals(p[3]),"message "+line+" actual="+units(value.get_Message()));check(value.getClass().getName().equals(p[4]),"type "+line);check(value.get_HResult()==Integer.parseInt(p[5]),"HRESULT "+line);check((value.get_InnerException()!=null)==p[6].equals("1"),"inner presence "+line);check(Objects.equals(value.get_InnerException()==null?null:value.get_InnerException().getClass().getName(),p[7].equals("~")?null:p[7]),"inner type "+line);check(units(value.get_InnerException()==null?null:value.get_InnerException().get_Message()).equals(p[8]),"inner message "+line);check((value.get_InnerException()==inner)==p[9].equals("1"),"inner identity "+line);check((value.GetBaseException()==(inner==null?value:inner))==p[10].equals("1"),"base identity "+line);groups+=8;cases++;}java.lang.System.out.println("PASS NullReferenceException message cases="+cases+" groups="+groups);}
}
